  /* ---------------- barra de progresso ---------------- */
  function initProgressBar(){
    var bar = document.querySelector('.progress-bar');
    if(!bar) return;
    function update(){
      var h = document.documentElement;
      var scrollTop = h.scrollTop || document.body.scrollTop;
      var height = h.scrollHeight - h.clientHeight;
      var pct = height > 0 ? (scrollTop / height) * 100 : 0;
      bar.style.width = pct + '%';
    }
    document.addEventListener('scroll', update, { passive:true });
    update();
  }

  /* ---------------- header some/aparece ao rolar ---------------- */
  function initHeaderAutoHide(){
    var header = document.getElementById('site-header');
    if(!header) return;
    var lastY = window.scrollY;
    var ticking = false;
    function onScroll(){
      var y = window.scrollY;
      if(Math.abs(y - lastY) > 6){
        if(y > lastY && y > 140){
          header.classList.add('is-hidden');
        } else {
          header.classList.remove('is-hidden');
        }
        lastY = y;
      }
      ticking = false;
    }
    document.addEventListener('scroll', function(){
      if(!ticking){
        window.requestAnimationFrame(onScroll);
        ticking = true;
      }
    }, { passive:true });
  }

  /* ---------------- reveal on scroll ---------------- */
  function initReveal(){
    var items = document.querySelectorAll('.reveal');
    if(!items.length) return;
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add('is-visible');
          io.unobserve(entry.target);
        }
      });
    }, { threshold:.15, rootMargin:'0px 0px -60px 0px' });
    items.forEach(function(el, i){
      el.style.setProperty('--i', i % 8);
      io.observe(el);
    });
  }

  /* ---------------- contadores animados ---------------- */
  function initCounters(){
    var counters = document.querySelectorAll('[data-count]');
    if(!counters.length) return;
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(!entry.isIntersecting) return;
        var el = entry.target;
        io.unobserve(el);
        var target = parseFloat(el.getAttribute('data-count'));
        var suffix = el.getAttribute('data-suffix') || '';
        var prefix = el.getAttribute('data-prefix') || '';
        var startFrac = target >= 10 ? 0.7 : 0; // números pequenos (ex: "4") contam do zero normalmente
        var duration = 1100;
        var start = null;
        function step(ts){
          if(start === null) start = ts;
          var progress = Math.min((ts - start) / duration, 1);
          var eased = 1 - Math.pow(1 - progress, 3);
          var value = Math.round(target * (startFrac + (1 - startFrac) * eased));
          el.textContent = prefix + value.toLocaleString('pt-BR') + suffix;
          if(progress < 1) requestAnimationFrame(step);
          else el.textContent = prefix + target.toLocaleString('pt-BR') + suffix;
        }
        requestAnimationFrame(step);
      });
    }, { threshold:.4 });
    counters.forEach(function(el){ io.observe(el); });
  }

  /* ---------------- contador de faturamento (baseado em tempo real, segue subindo sozinho) ---------------- */
  function formatBRL(value){
    return 'R$' + value.toLocaleString('pt-BR', {minimumFractionDigits:2, maximumFractionDigits:2});
  }
  function initRevenueCounter(){
    var el = document.getElementById('revenue-counter');
    if(!el) return;
    var base = parseFloat(el.getAttribute('data-base')) || 0;
    var anchor = parseFloat(el.getAttribute('data-anchor')) || Date.now();
    var perSecond = parseFloat(el.getAttribute('data-per-second')) || 0;
    var spikeAmount = parseFloat(el.getAttribute('data-spike-amount')) || 0;
    var spikeDays = parseFloat(el.getAttribute('data-spike-days')) || 0;
    var started = false;

    function currentValue(){
      var elapsedSeconds = Math.max(0, (Date.now() - anchor) / 1000);
      var value = base + elapsedSeconds * perSecond;
      if(spikeDays > 0 && spikeAmount > 0){
        var spikes = Math.floor((elapsedSeconds / 86400) / spikeDays);
        value += spikes * spikeAmount;
      }
      return value;
    }

    // encolhe a fonte só o necessário pra caber na caixa (a largura do texto
    // muda quando a quantidade de dígitos muda, ex: virar de 8 pra 9 dígitos
    // daqui a alguns meses) — recalcula só quando o comprimento do texto
    // muda, não a cada frame, pra não pesar na animação.
    var lastLen = -1;
    var maxFontPx = null;
    function fitFont(){
      if(maxFontPx === null){
        maxFontPx = parseFloat(window.getComputedStyle(el).fontSize);
      }
      el.style.fontSize = maxFontPx + 'px';
      if(el.scrollWidth > el.clientWidth && el.clientWidth > 0){
        var scale = el.clientWidth / el.scrollWidth;
        el.style.fontSize = (maxFontPx * scale * 0.97) + 'px';
      }
    }
    function setText(text){
      el.textContent = text;
      if(text.length !== lastLen){
        lastLen = text.length;
        fitFont();
      }
    }
    window.addEventListener('resize', function(){ maxFontPx = null; lastLen = -1; setText(el.textContent); }, { passive:true });

    function tick(){
      setText(formatBRL(currentValue()));
    }

    // depois da animação de entrada, o contador segue rodando sozinho,
    // atualizando a cada frame (os centavos giram continuamente, os reais
    // sobem devagar) — assim fica visivelmente "vivo" e nunca parece parado.
    function liveLoop(){
      tick();
      requestAnimationFrame(liveLoop);
    }

    function countUp(){
      if(started) return;
      started = true;
      // anima subindo do valor-base (nunca zero, nunca decrescendo) até o
      // valor real ao vivo agora; depois disso segue incrementando sozinho.
      var target = currentValue();
      var from = Math.min(base, target);
      var duration = 1600, start = null;
      function step(ts){
        if(start === null) start = ts;
        var progress = Math.min((ts - start) / duration, 1);
        var eased = 1 - Math.pow(1 - progress, 3);
        setText(formatBRL(from + (target - from) * eased));
        if(progress < 1){
          requestAnimationFrame(step);
        } else {
          liveLoop();
        }
      }
      requestAnimationFrame(step);
    }

    if(!('IntersectionObserver' in window)){ countUp(); return; }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){ countUp(); io.unobserve(entry.target); }
      });
    }, { threshold:.4 });
    io.observe(el);
  }

  /* ---------------- timeline: bolinha acende ao entrar na tela ---------------- */
  function initTimeline(){
    var steps = document.querySelectorAll('.timeline-step');
    if(!steps.length) return;
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add('is-active');
        }
      });
    }, { threshold:.5 });
    steps.forEach(function(el){ io.observe(el); });
  }

  /* ---------------- ecossistema: esferas orbitando ao entrar na tela ---------------- */
  function initEcosystem(){
    var ecos = document.querySelectorAll('.ecosystem');
    if(!ecos.length) return;
    if(!('IntersectionObserver' in window)){
      ecos.forEach(function(eco){ eco.classList.add('is-active'); });
      return;
    }
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if(entry.isIntersecting){
          entry.target.classList.add('is-active');
          io.unobserve(entry.target);
        }
      });
    }, { threshold:.35 });
    ecos.forEach(function(eco){ io.observe(eco); });
  }

  /* ---------------- FAQ accordion ---------------- */
  function initFaq(){
    var items = document.querySelectorAll('.faq-item');
    items.forEach(function(item){
      var q = item.querySelector('.faq-q');
      var a = item.querySelector('.faq-a');
      if(!q || !a) return;
      q.addEventListener('click', function(){
        var isOpen = item.classList.contains('is-open');
        items.forEach(function(other){
          other.classList.remove('is-open');
          other.querySelector('.faq-a').style.maxHeight = null;
        });
        if(!isOpen){
          item.classList.add('is-open');
          a.style.maxHeight = a.scrollHeight + 'px';
        }
      });
    });
  }

  /* ---------------- formulário de contato -> WhatsApp ---------------- */
  function initContactForm(){
    var form = document.getElementById('contact-form');
    if(!form) return;
    var WHATSAPP_NUMBER = '5511999999999'; // TODO: substituir pelo número real (formato DDI+DDD+numero)
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var nome = form.nome.value.trim();
      var empresa = form.empresa.value.trim();
      var whats = form.whatsapp.value.trim();
      var msg = form.mensagem.value.trim();
      var text = 'Olá, Dom Partner Growth! Meu nome é ' + nome +
                 (empresa ? ' (' + empresa + ')' : '') +
                 '. ' + (msg ? msg : 'Quero conversar sobre uma parceria de crescimento.') +
                 (whats ? ' Meu WhatsApp: ' + whats : '');
      var url = 'https://wa.me/' + WHATSAPP_NUMBER + '?text=' + encodeURIComponent(text);
      window.open(url, '_blank');
    });
  }

